<script setup>
import {ref,onMounted} from 'vue'
import {useLearning} from '../store'
const store=useLearning(),documents=ref([]),traces=ref([]),file=ref(null),kid=ref(''),source=ref('自编演示资料'),question=ref(''),busy=ref(false),message=ref('')
// The vector index and call traces are platform-wide, so only the platform admin sees them.
const platformAdmin=()=>store.user.role==='admin'
async function load(){[documents.value,traces.value]=await Promise.all([store.api('/assistant/admin/documents'),platformAdmin()?store.api('/assistant/admin/traces'):[]])}
async function upload(){if(!file.value)return;busy.value=true;await store.run(async()=>{const data=new FormData();data.append('file',file.value);if(kid.value)data.append('knowledge_id',kid.value);data.append('source',source.value);if(question.value)data.append('question_id',question.value);const v=await store.api('/assistant/admin/documents',{method:'POST',body:data});message.value=v.status==='failed'?v.error:'资料解析完成，请重建向量索引。';await load()});busy.value=false}
async function mutate(path,method){await store.run(async()=>{await store.api(path,{method});await load()})}
async function rebuild(){busy.value=true;await store.run(async()=>{const result=await store.api('/assistant/admin/index/rebuild',{method:'POST'});message.value=`索引已更新：${result.chunks} 个片段 / ${result.dimension} 维`;await load()});busy.value=false}
onMounted(()=>{if(store.isStaff)store.run(load)})
</script>
<template><div v-if="!store.isStaff" class="empty">需要本课程老师或助教权限</div><template v-else><div class="page-heading"><div><p class="eyebrow">课程管理 · 资料与检索</p><h1>{{ store.currentCourse?.name }} 知识库</h1><p>管理自编讲义与受限解析，所有导入均保留来源；不包含评测标准答案。</p></div><button v-if="store.user.role==='admin'" class="primary" :disabled="busy" @click="rebuild">{{ busy?'处理中…':'重建向量索引' }}</button></div><p class="callout" v-if="message">{{ message }}</p><form class="panel" @submit.prevent="upload"><div class="form-grid"><label>资料文件（MD / TXT / 文本型 PDF，≤5MB）<input type="file" accept=".md,.txt,.pdf" required @change="file=$event.target.files[0]"/></label><label>知识点<select v-model="kid"><option value="">整门课程（不指定知识点）</option><option v-for="n in store.nodes" :value="n.id" :key="n.id">{{ n.name }}</option></select></label><label>来源说明<input v-model="source" required minlength="3" maxlength="255"/></label><label>受限题目 ID（留空为公共讲义）<input v-model="question" type="number" min="1" placeholder="只允许已提交该题的学生查看"/></label></div><button class="secondary" :disabled="busy">导入资料</button><p class="muted">扫描 PDF 需要 OCR，本阶段不支持。导入失败可查看原因；新资料解析后，关键词检索可用，向量检索需重建索引。</p></form><div class="panel table-scroll"><table><thead><tr><th>文档</th><th>来源 / 权限</th><th>处理状态</th><th>片段</th><th>操作</th></tr></thead><tbody><tr v-for="d in documents" :key="d.id"><td>{{ d.title }}<small class="doc-id">{{ d.id }}</small></td><td>{{ d.source }}<br>{{ d.scope==='public'?'公共讲义':'已提交题目解析' }}</td><td>{{ d.status }}<br>{{ d.error }}</td><td>{{ d.chunks }}</td><td><button class="text-button" @click="mutate(`/assistant/admin/documents/${d.id}/toggle`,'POST')">{{ d.active?'停用':'启用' }}</button> <button class="text-button" @click="mutate(`/assistant/admin/documents/${d.id}`,'DELETE')">删除</button></td></tr></tbody></table></div><details class="panel"><summary>管理员调试视图 · 最近 30 次请求</summary><article v-for="t in traces" :key="t.id" class="trace"><strong>{{ t.status }} · {{ t.metadata.provider_mode }} · {{ t.metadata.elapsed_ms }} ms</strong><p>{{ t.id }} · {{ t.metadata.model }} · {{ t.metadata.error||'无应用错误' }}</p><p>输入 / 输出 Token：{{ t.metadata.usage?`${t.metadata.usage.input_tokens} / ${t.metadata.usage.output_tokens}`:'未知（提供方未返回）' }}</p><div v-for="(tool,i) in t.tools" :key="i">{{ tool.name }} · {{ tool.status }} · {{ tool.elapsed_ms }} ms <code>{{ tool.arguments }}</code></div></article></details></template></template>
<style scoped>.doc-id{display:block;color:var(--muted);font-size:9px}.trace{padding:15px 0;border-bottom:1px solid var(--border);overflow-wrap:anywhere}.trace p{font-size:11px;margin:6px 0}.trace code{font-size:10px}.panel>p{font-size:12px;margin-top:15px}</style>
